!function(){function t(t){return function(t){if(Array.isArray(t))return e(t)}(t)||function(t){if("undefined"!=typeof Symbol&&null!=t[Symbol.iterator]||null!=t["@@iterator"])return Array.from(t)}(t)||function(t,r){if(t){if("string"==typeof t)return e(t,r);var n={}.toString.call(t).slice(8,-1);return"Object"===n&&t.constructor&&(n=t.constructor.name),"Map"===n||"Set"===n?Array.from(t):"Arguments"===n||/^(?:Ui|I)nt(?:8|16|32)(?:Clamped)?Array$/.test(n)?e(t,r):void 0}}(t)||function(){throw new TypeError("Invalid attempt to spread non-iterable instance.\nIn order to be iterable, non-array objects must have a [Symbol.iterator]() method.")}()}function e(t,e){(null==e||e>t.length)&&(e=t.length);for(var r=0,n=Array(e);r<e;r++)n[r]=t[r];return n}System.register(["./index-legacy-BXoGhlMF.js"],function(e,r){"use strict";var n,s,o,i,p,m;return{setters:[function(t){n=t.G,s=t.c,o=t.a,i=t.b,p=t.d,m=t.o}],execute:function(){var r={class:"cm-art-container",itemscope:"",itemtype:"https://schema.org/Article"};e("default",n({__name:"article",setup:function(e){return function(e,n){return m(),s("div",r,t(n[0]||(n[0]=[o('<h2 class="cm-art-title" itemprop="headline">图片在线预览：在浏览器中直接查看任意 URL 图片</h2><p class="cm-art-desc" itemprop="description">无需下载即可预览远程图片，支持全屏查看、格式检测与尺寸信息展示，一个轻量级的在线图片查看器。</p><section class="cm-art-section"><h3>为什么需要在线图片预览？</h3><p>在日常上网过程中，你一定遇到过这些场景：朋友发了一个图片链接但你不确定内容是否安全、想快速查看某个 CDN 上的资源图片是否正常加载、需要确认一张远程图片的实际尺寸和格式信息、或者只是不想为了看一张图而下载到本地。传统的做法是点击链接让浏览器直接打开——但这样做有几个问题：<strong>大图会导致页面卡顿</strong>（浏览器会尝试渲染原始分辨率）、<strong>无法获取图片元数据</strong>（尺寸、格式、文件大小）、<strong>某些链接可能指向非图片内容</strong>（存在安全风险）。</p><p>本工具通过在独立容器中加载远程图片来解决这些问题。输入任意图片 URL 后，工具会在受控环境中渲染图片，同时提供<strong>全屏预览</strong>、<strong>错误检测</strong>和<strong>加载状态反馈</strong>。整个过程不需要将图片下载到你的设备上——如果你只是「看看」，那就不应该产生任何本地文件。</p></section><section class="cm-art-section"><h3>支持的图片格式与限制</h3><p>本工具支持所有浏览器原生能够解析的图片格式，包括但不限于：</p><ul><li><strong>JPEG / JPG</strong>——最通用的有损压缩格式，适合照片类内容，文件小兼容性好。</li><li><strong>PNG</strong>——无损压缩格式，支持透明通道，适合图标、截图、需要高质量的场景。</li><li><strong>GIF</strong>——支持动画帧，适合简单动图预览（注意：浏览器对 GIF 帧率的处理可能不一致）。</li><li><strong>WebP</strong>——Google 推出的新一代格式，比 JPEG 更小质量更好，现代浏览器全面支持。</li><li><strong>SVG</strong>——矢量图形格式，可无限缩放不失真，但建议使用专门的 SVG 查看器以获得更好的代码查看体验。</li><li><strong>BMP / ICO / TIFF</strong>——较老或不常用的格式，大多数浏览器仍能识别并渲染。</li></ul><p>需要注意的是，由于浏览器的<strong>跨域安全策略（CORS）</strong>限制，部分开启了严格 CORS 策略的服务器可能阻止图片被跨域加载。如果遇到图片无法显示的情况，首先检查目标服务器是否允许跨域访问。</p></section>',4),i("section",{class:"cm-art-faq",itemscope:"",itemtype:"https://schema.org/FAQPage"},[i("h3",null,"常见问题"),i("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[i("summary",{itemprop:"name"},"输入 URL 后显示空白或报错怎么办？"),i("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[i("p",{itemprop:"text"},[p("可能的原因有以下几种：（1）"),i("strong",null,"URL 格式错误"),p("——确保以 `http://` 或 `https://` 开头，且链接指向的是直接的图片文件（而非包含图片的网页）；（2）"),i("strong",null,"CORS 跨域限制"),p("——目标服务器禁止了跨域图片加载，这种情况下浏览器控制台会有具体的错误提示；（3）"),i("strong",null,"链接已失效"),p("——图片可能已被删除或链接过期；（4）"),i("strong",null,"需要认证"),p("——某些图片链接需要登录或特定 Cookie 才能访问。你可以先尝试用浏览器新标签页直接打开该 URL 进行排查。")])])]),i("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[i("summary",{itemprop:"name"},"可以预览 base64 编码的图片吗？"),i("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[i("p",{itemprop:"text"},"理论上可以——只要将完整的 `data:image/...;base64,...` 字符串粘贴到 URL 输入框中即可。不过 base64 字符串通常非常长（一张普通照片编码后可能有几十万字符），直接粘贴到输入框中不太方便。如果你的需求是预览 base64 图片，更推荐使用开发者工具的 Console 面板或专门的 Base64 解码工具来处理。")])]),i("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[i("summary",{itemprop:"name"},"预览的图片会被保存到服务器吗？"),i("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[i("p",{itemprop:"text"},[i("strong",null,"不会。"),p("本工具的所有处理都在你的浏览器本地完成，图片数据从源服务器直接传输到你的浏览器，中间不经过任何第三方服务器存储。这意味着你的预览历史不会被记录、图片内容不会被上传、不存在隐私泄露风险。这也是「纯前端工具」相比传统后端服务的核心优势之一。")])])]),i("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[i("summary",{itemprop:"name"},"和直接在浏览器打开图片链接有什么区别？"),i("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[i("p",{itemprop:"text"},[p("主要区别在于"),i("strong",null,"可控性和信息展示"),p("：直接打开时，浏览器会用默认方式渲染图片（通常是以原始尺寸显示），超大图片可能导致浏览器卡顿甚至崩溃；而本工具会在容器内自适应缩放显示，同时提供加载状态指示和错误提示。此外，未来版本可能会加入 EXIF 信息读取、颜色分析、格式转换等增强功能——这些都是直接打开无法提供的。")])])]),i("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[i("summary",{itemprop:"name"},"手机上可以使用吗？"),i("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[i("p",{itemprop:"text"},"完全可以。本工具采用响应式设计，在手机浏览器上的操作流程与 PC 端一致：输入 URL → 点击预览 → 点击图片进入全屏模式。一个小技巧：在微信或 QQ 中收到图片链接时，可以选择「在浏览器中打开」然后访问本工具页面进行预览，避免直接在聊天应用内打开可能带来的安全风险或格式问题。")])]),i("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[i("summary",{itemprop:"name"},"能用来检测图片是否被防盗链吗？"),i("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[i("p",{itemprop:"text"},[p("可以作为一个初步的检测手段。如果图片在本工具中能正常显示但在你的网页中显示不出来（出现裂图或 403 错误），很可能是目标网站设置了 "),i("code",null,"Referer"),p(" 检查防盗链机制——即只允许从特定域名（通常是它们自己的网站）引用图片。本工具的请求 Referer 是当前页面域名，与你的网站不同，因此可以用来判断是否存在防盗链限制。要解决防盗链问题，可以在你的网页中使用 `"),i("img",{referrerpolicy:"no-referrer"}),p("` 属性或通过服务端代理转发图片请求。")])])])],-1)])))}}}))}}})}();
